body:
{
  "pains": [
    {
      "id": "pain:pajama-time",
      "statement": "I see patients all day and then do the actual paperwork at ten at night, after everyone else is asleep.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "Notes are not finished when the clinic day ends, so documentation follows the clinician home.",
        "operational": "Roughly six hours in the EHR for every eight scheduled clinical hours, with about three of those on documentation and clerical work; 22% of physicians put in more than eight extra EHR hours a week on nights and weekends.",
        "personal": "The unpaid second shift lands on family time, and it is the single thing physicians name most often when they describe why they are burned out."
      },
      "workflow": "Epic In Basket and note queue after the last patient leaves: open encounters, unsigned notes, results to route, and refill requests, done from a laptop at the kitchen table.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A full clinic day where the schedule runs over and the note queue is still open at 6pm", "cites": ["src:4"] },
        { "event": "Annual burnout or wellness survey results land in front of leadership", "cites": ["src:2", "src:10"] }
      ],
      "who_feels": ["end_user", "champion", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "By the time the clinic day ends, 22 percent of physicians spend more than eight additional hours per week in the EHR after hours, nights, weekends, before the family is awake.", "cites": ["src:4"] },
            { "situation": "venting", "verbatim": "clinical documentation in the electronic health record (EHR) has become increasingly burdensome for physicians and is a major driver of clinician burnout and dissatisfaction.", "cites": ["src:13"] },
            { "situation": "when_comparing", "verbatim": "I get about an hour back every day that I can use to call patients back.", "cites": ["src:2"] }
          ],
          "costs_them": "One to two hours of unpaid evening work per clinic day, taken out of sleep and family time.",
          "fears": "That this is simply what the job is now, and that cutting back to part time is the only lever they actually control.",
          "dream_outcome": "Walking out of the building with every note signed."
        },
        "economic_buyer": {
          "says": [
            { "situation": "to_their_boss", "verbatim": "Ambient scribe technology means that providers can focus on the patient during a visit instead of the computer and avoid the dreaded after-hours 'pajama time' catching up on documentation.", "cites": ["src:10"] }
          ],
          "costs_them": "Turnover and reduced-FTE requests from the clinicians who are hardest and most expensive to replace.",
          "fears": "Losing a service line because two of its four physicians drop to 0.6 FTE.",
          "dream_outcome": "After-hours EHR minutes per clinician falling quarter over quarter in the Signal data they already report."
        }
      },
      "segments": ["seg:system", "seg:specialty"],
      "feature_ref": "feat:clinician",
      "cites": ["src:4", "src:2", "src:10", "src:13"]
    },
    {
      "id": "pain:screen-between-us",
      "statement": "I spend the visit typing with my back half turned, and the patient can tell I am not really listening.",
      "element": "b2b:individual:fun_and_perks",
      "shape": {
        "surface": "The clinician is looking at a monitor instead of the person in the room.",
        "operational": "History and plan get typed live during the encounter, so attention splits between the conversation and the keyboard; what does not get typed has to be reconstructed later from memory.",
        "personal": "This is the part of the job people went to medical or nursing school for, and it is the part the EHR took. Clinicians describe getting it back as joy, not efficiency."
      },
      "workflow": "The exam room itself, during history-taking and the assessment-and-plan discussion, with Epic open on a workstation-on-wheels or a laptop between clinician and patient.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A patient comments on the typing, or praises being listened to when the clinician stops", "cites": ["src:13", "src:3"] },
        { "event": "Patient experience scores reviewed at a department meeting", "cites": ["src:2"] }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "I feel like I can be more face-to-face with them and [have] more eye contact. I feel like I can establish a better relationship instead of staring at the computer and looking like I'm doing all my work and not paying attention to them.", "cites": ["src:3"] },
            { "situation": "when_comparing", "verbatim": "It definitely improves my joy in practice because I get to interact with patients and look them in the eye.", "cites": ["src:2"] },
            { "situation": "when_comparing", "verbatim": "I even had a patient praise the fact that I could listen instead of type during the visit.", "cites": ["src:13"] }
          ],
          "costs_them": "The relationship part of the encounter, and the sense that the work is still medicine rather than data entry.",
          "fears": "Missing something the patient said sideways, because half their attention was on the keyboard.",
          "dream_outcome": "Sitting down, facing the patient, and never touching the keyboard during the visit."
        },
        "champion": {
          "says": [
            { "situation": "to_their_boss", "verbatim": "Definitely improves my contact with patients and families, and definitely makes clinic easier.", "cites": ["src:2"] }
          ],
          "costs_them": "Credibility when they tell colleagues a tool is worth changing their workflow for.",
          "fears": "Championing something that gets taken away in the next budget cycle.",
          "dream_outcome": "Colleagues asking how they got it, unprompted."
        }
      },
      "segments": ["seg:system", "seg:specialty"],
      "feature_ref": "feat:clinician",
      "cites": ["src:3", "src:2", "src:13"]
    },
    {
      "id": "pain:edit-tax",
      "statement": "It hands me nine paragraphs when I needed three, so now I am editing instead of writing and it takes just as long.",
      "element": "b2b:ease_of_doing_business:reduced_effort",
      "shape": {
        "surface": "The draft arrives verbose, over-formal, and organised like a transcript rather than like a clinician's reasoning.",
        "operational": "Work moves from composing to reviewing and trimming. For some clinicians the review is longer than the note they used to write; for others it is genuinely faster. The variance is the problem.",
        "personal": "Reviewing someone else's prose is a different and more tedious cognitive task than writing your own, and it lands at the end of a long day when attention is worst."
      },
      "workflow": "The post-encounter step in Epic: the AI draft lands in the note, and the clinician edits the HPI and assessment-and-plan before signing.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A long or multi-problem visit where the draft balloons", "cites": ["src:3", "src:2"] },
        { "event": "A vendor release changes the draft's length or tone", "cites": ["src:3"] }
      ],
      "who_feels": ["end_user", "economic_buyer", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "It's probably actually taking me longer now because I'm doing more editing in the top part of my note than I would have done before.", "cites": ["src:3"] },
            { "situation": "venting", "verbatim": "It added 1 to 2 hours a day to my note writing", "cites": ["src:2"] },
            { "situation": "when_refusing", "verbatim": "So there would be patients that I just knew it was going to end up being a massive block of text if I use the tool. And I would much rather go in with my own free text, like short form documentation.", "cites": ["src:3"] },
            { "situation": "venting", "verbatim": "The AI-generated text is also superfluous, leading to bulky notes...Errors tend to be minor but are frequent.", "cites": ["src:2"] }
          ],
          "costs_them": "The time savings they were promised, and in the worst cases more time than before.",
          "fears": "Being told the tool works and they are using it wrong.",
          "dream_outcome": "A draft short enough and shaped enough like their own note that they sign it with one read."
        },
        "economic_buyer": {
          "says": [
            { "situation": "when_comparing", "verbatim": "When I'm expecting three lines and I get nine paragraphs, that creates extra cognitive burden.", "cites": ["src:12"] }
          ],
          "costs_them": "The efficiency case they made internally, once clinicians report editing time instead of saved time.",
          "fears": "Paying per seat for a tool that moved the burden instead of removing it.",
          "dream_outcome": "Edit time per note trending down across the deployed population, not just median satisfaction going up."
        }
      },
      "segments": ["seg:system", "seg:specialty"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company addresses draft length or house style. What would kill this is per-clinician and per-specialty control over draft length, structure and voice, which the company does not name as a capability.",
      "cites": ["src:3", "src:2", "src:12"]
    },
    {
      "id": "pain:note-bloat-buries-the-patient",
      "statement": "I open a colleague's note and five minutes later I still do not know who this patient is.",
      "element": "b2b:functional:product_quality",
      "shape": {
        "surface": "Notes are long, padded and repetitive, and the clinically useful sentences are buried.",
        "operational": "Note length in the US grew 60% between 2009 and 2018 and redundancy grew 11%; a 2020 analysis found 54% of the text in a typical chart is copied forward. The next reader has to hunt.",
        "personal": "Reading a chart badly is how you miss something, and the person who signs the next note carries that."
      },
      "workflow": "Chart review before a consult, a handoff, or an admission: paging through prior notes in Epic Chart Review trying to assemble the story before the patient is in front of you.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Picking up a patient cold from another service or another practice", "cites": ["src:4"] },
        { "event": "An AI draft that reads as a transcript rather than as clinical reasoning", "cites": ["src:3"] }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Five minutes pass. You still do not know who this patient is.", "cites": ["src:4"] },
            { "situation": "venting", "verbatim": "More than half the text in a typical chart, 54 percent by a 2020 analysis, is copied forward from prior documentation. Not updated. Not reviewed for accuracy. Copied.", "cites": ["src:4"] },
            { "situation": "when_comparing", "verbatim": "It did a great job of storytelling, but probably not organizing and synthesizing things in a way that a clinician thinks.", "cites": ["src:3"] },
            { "situation": "when_comparing", "verbatim": "Because what it does is, in the history section, it's too verbose.", "cites": ["src:3"] }
          ],
          "costs_them": "Minutes per chart, repeated across every consult and handoff, plus the risk of missing a detail that was in there somewhere.",
          "fears": "A miss that was technically documented but practically invisible.",
          "dream_outcome": "Opening a note and knowing the patient in thirty seconds."
        }
      },
      "segments": ["seg:system", "seg:specialty"],
      "feature_ref": "feat:clinician",
      "cites": ["src:4", "src:3"]
    },
    {
      "id": "pain:my-name-on-a-note-i-did-not-write",
      "statement": "It puts a polished note in front of me at the end of a long day and I am the one who signs it, wrong medication and all.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "The draft reads clean and confident whether or not it is right.",
        "operational": "Reported error types include incorrect medication names and dosages, fabricated or inaccurate history, statements misattributed between patient and clinician, and omitted discussion of diagnoses or treatment. A note that looks finished invites skimming rather than scrutiny.",
        "personal": "The legal and professional exposure does not transfer to the vendor. The signature is theirs."
      },
      "workflow": "The sign-off step in Epic at the end of clinic, reviewing a queue of AI drafts when attention is lowest.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Catching a hallucinated or misattributed detail in a draft", "cites": ["src:5", "src:3"] },
        { "event": "A malpractice or safety committee asks who reviewed the note", "cites": ["src:5", "src:8"] }
      ],
      "who_feels": ["end_user", "blocker", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Physicians remain responsible for every word in the chart.", "cites": ["src:5"] },
            { "situation": "venting", "verbatim": "If an AI-generated note appears polished and complete, the temptation is to skim rather than scrutinize. That temptation may be particularly strong at the end of a long clinic day.", "cites": ["src:5"] },
            { "situation": "when_it_bites", "verbatim": "It makes mistakes and typos and hears things wrong, occasionally homonyms and other things and I have to fix it because it sounds funny.", "cites": ["src:3"] }
          ],
          "costs_them": "A review they cannot safely skip, which eats the time the tool was supposed to give back.",
          "fears": "Signing a fabricated medication dose and finding out in a deposition.",
          "dream_outcome": "Being able to see, fast, exactly which parts of the note came from something the patient actually said."
        },
        "technical_evaluator": {
          "says": [
            { "situation": "when_comparing", "verbatim": "I've seen large language models give completely different responses. And one of those responses would probably cause patient harm if used.", "cites": ["src:12"] }
          ],
          "costs_them": "Owning the safety case for a tool whose output varies run to run.",
          "fears": "A patient safety event traced to an AI-drafted note on their watch.",
          "dream_outcome": "Traceability from every clinical claim in the note back to the audio."
        },
        "blocker": {
          "says": [
            { "situation": "when_refusing", "verbatim": "If a physician passively approves an AI-generated note with embedded inaccuracies, who is responsible when an audit reveals discrepancies?", "cites": ["src:8"] }
          ],
          "costs_them": "Unclear accountability across clinician, vendor and organisation.",
          "fears": "Discovering the attribution question only after an audit or claim.",
          "dream_outcome": "A documented review standard that holds up under audit."
        }
      },
      "segments": ["seg:system", "seg:specialty", "seg:nursing"],
      "feature_ref": null,
      "feature_note": "Nothing in brain/company reduces review risk. What would is an accuracy surface that links each statement in the note to the moment in the conversation it came from, plus a review record that survives audit.",
      "cites": ["src:5", "src:3", "src:12", "src:8"]
    },
    {
      "id": "pain:consent-derails-the-open",
      "statement": "Now I have to open every visit by asking permission to record, and that is the exact minute the patient decides how much to tell me.",
      "element": "b2b:table_stakes:ethical_standards",
      "shape": {
        "surface": "The first words of the encounter are about a recording device rather than about the patient.",
        "operational": "In two-party consent states recording without consent is a wiretapping violation, so the disclosure cannot be skipped. Some patients consent, then see the note and withdraw. A checkbox in the chart is not the same as an informed conversation.",
        "personal": "Clinicians spend the opening of the visit defending a vendor's presence instead of building trust, and psychiatry and adolescent visits are where it hurts most."
      },
      "workflow": "The first sixty seconds of the encounter, before history-taking, with the app open on a phone in the room.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "A patient declines, or consents and then reads the note and withdraws", "cites": ["src:3"] },
        { "event": "A class action or state privacy complaint over unconsented recording", "cites": ["src:7"] }
      ],
      "who_feels": ["end_user", "blocker"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "It can derail the opening of the appointment, the minutes where the patient decides how much of themselves to bring into the room.", "cites": ["src:7"] },
            { "situation": "when_it_bites", "verbatim": "There have been just 2 patients who had initially consented and then they looked at the notes and then they felt uncomfortable and then they messaged me back and said, 'don't use this ever again.'", "cites": ["src:3"] }
          ],
          "costs_them": "The opening of the visit, and in sensitive specialties some of the disclosure they needed.",
          "fears": "That a patient holds back something important because a machine is listening.",
          "dream_outcome": "A consent step that takes ten seconds and does not change what the patient is willing to say."
        },
        "blocker": {
          "says": [
            { "situation": "when_refusing", "verbatim": "In two-party states like California, Illinois, and Pennsylvania, recording a patient without consent is a wiretapping violation.", "cites": ["src:7"] },
            { "situation": "when_refusing", "verbatim": "A consent checkbox with nothing behind it is the latter. It records that the disclosure occurred without providing anything that would make it adequate.", "cites": ["src:7"] }
          ],
          "costs_them": "Legal exposure across every state the system operates in.",
          "fears": "A class action over recordings the organisation cannot prove were consented to.",
          "dream_outcome": "A consent workflow that is defensible in the strictest state they operate in."
        }
      },
      "segments": ["seg:system", "seg:specialty"],
      "feature_ref": null,
      "feature_note": "brain/company names no consent capability. What would kill this is a consent flow built into the encounter with a per-state policy and a durable record of what the patient was told.",
      "cites": ["src:7", "src:3"]
    },
    {
      "id": "pain:nurses-chart-it-twice",
      "statement": "I chart the assessment in the flowsheet and then write the same thing again in a shift note, and none of it changes the patient's care.",
      "element": "b2b:ease_of_doing_business:simplification",
      "shape": {
        "surface": "The same finding gets entered in several places, and information has to be looked up in more than one place too.",
        "operational": "79% of acute care nurses report time lost to unproductive charting. Multiple valid paths through the same task make documentation inconsistent as well as slow.",
        "personal": "Nurses describe finishing a shift exhausted with little to show for it, and charting is the enhancement they ask for more than any other."
      },
      "workflow": "Epic inpatient flowsheets during the shift plus an end-of-shift narrative note, charted at a workstation on wheels or after handoff rather than at the bedside.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A heavy-acuity shift where charting backs up and stays after the shift ends", "cites": ["src:9"] },
        { "event": "A policy change that adds a required field or a second place to document", "cites": ["src:9"] }
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "We are required to double chart by management. We are required to do chart assessments in the flowsheet, then write an end-of-shift skilled note...", "cites": ["src:9"] },
            { "situation": "venting", "verbatim": "A lot of our charting feels like a waste of time because it doesn't make a difference in the delivery of patient care...", "cites": ["src:9"] },
            { "situation": "to_their_boss", "verbatim": "Stop putting the same thing to chart in multiple places on flowsheets. It just bogs things down and is distracting.", "cites": ["src:9"] },
            { "situation": "when_it_bites", "verbatim": "It feels as though [we] are frequently forced to double chart and/or check two places for information...exhausted with very little to show for it...", "cites": ["src:9"] }
          ],
          "costs_them": "Hours of a twelve-hour shift spent on entries that change nothing, and time taken from the bedside.",
          "fears": "Missing a required field and being written up for a charting gap rather than a care gap.",
          "dream_outcome": "Saying it once at the bedside and having it land wherever it needs to land."
        },
        "economic_buyer": {
          "says": [
            { "situation": "to_their_boss", "verbatim": "I would say the sheer amount of charting that I have to do in my shift can be too much sometimes.", "cites": ["src:9"] }
          ],
          "costs_them": "Nursing turnover and agency spend in the units with the heaviest documentation load.",
          "fears": "Losing experienced floor nurses over charting rather than over pay.",
          "dream_outcome": "Documented time at the bedside going up, and charting complaints falling out of the top of the nursing survey."
        }
      },
      "segments": ["seg:nursing", "seg:system"],
      "feature_ref": "feat:nursing",
      "cites": ["src:9"]
    },
    {
      "id": "pain:cannot-show-the-money",
      "statement": "My clinicians love it, but I cannot put a number in front of the CFO.",
      "element": "b2b:functional:cost_reduction",
      "shape": {
        "surface": "Satisfaction scores are strong and the financial case is not.",
        "operational": "Early multi-system evaluation found ambient scribes likely reduce burnout but leave financial impact unclear, with gaps in evidence on productivity and financial performance and no standard metrics across systems. Published studies are few and use heterogeneous measures.",
        "personal": "The CMIO who sponsored the rollout has to defend renewal on anecdote, which is a bad position when every AI line item is being questioned at once."
      },
      "workflow": "Annual budget and renewal review: per-clinician per-month licence cost against wRVU, coding intensity, after-hours EHR minutes and visit volume pulled from Epic Signal and the revenue cycle system.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Renewal or expansion request goes to finance", "cites": ["src:11", "src:10"] },
        { "event": "A pilot ends and someone asks what it bought", "cites": ["src:10"] }
      ],
      "who_feels": ["economic_buyer", "champion", "technical_evaluator"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Yeah, our clinicians love ambient tools. But I need to see the money. We need to see revenue generation or cost savings", "cites": ["src:11"] },
            { "situation": "when_comparing", "verbatim": "Yet health systems need to be clear about what they hope these tools will achieve in terms of overall performance and efficiency, and they need to measure the results.", "cites": ["src:10"] },
            { "situation": "when_comparing", "verbatim": "User experience and rigorous outcomes analysis are critical for getting any new technology right, especially one with such immense potential.", "cites": ["src:10"] }
          ],
          "costs_them": "A large per-seat line item defended on survey data rather than dollars.",
          "fears": "Funding an enterprise rollout and being asked in year two to show the return, with nothing to show.",
          "dream_outcome": "A defensible number: coding intensity, throughput or retention, measured the same way every quarter."
        },
        "champion": {
          "says": [
            { "situation": "to_their_boss", "verbatim": "It's quite clear scribes are increasing coding intensity. One hundred percent", "cites": ["src:11"] }
          ],
          "costs_them": "Political capital spent on a tool whose value they can feel but not evidence.",
          "fears": "Watching the licences get cut in a cost-reduction round.",
          "dream_outcome": "The finance team producing the ROI case themselves, from data the tool already emits."
        }
      },
      "segments": ["seg:system"],
      "feature_ref": "feat:rcm",
      "cites": ["src:11", "src:10"]
    },
    {
      "id": "pain:works-for-some-clinicians-not-all",
      "statement": "It is great for a sore throat and useless for my well-child exams and my interpreter visits.",
      "element": "b2b:functional:scalability",
      "shape": {
        "surface": "The same tool that delights one clinician is abandoned by the one down the hall.",
        "operational": "Fit collapses on visit types where little clinically relevant material is spoken aloud (physical exams), on very long encounters that get over-compressed (psychiatry), and on interpreter-mediated or accented encounters. Under half of enrolled clinicians used AI drafts for most of their notes.",
        "personal": "Clinicians who were excited and then found it did not help feel foolish, and they are the loudest voices in the next department meeting."
      },
      "workflow": "Enterprise rollout across 40+ specialties: licences assigned in Epic, then utilisation reports showing who actually kept using it after week four.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Utilisation report shows a specialty at near-zero use after go-live", "cites": ["src:2"] },
        { "event": "A clinician tries it on a visit type it handles badly and stops", "cites": ["src:3"] }
      ],
      "who_feels": ["economic_buyer", "end_user", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_refusing", "verbatim": "Most of my visits are physical exams as a pediatrician and do not work well...I basically use to make sure I don't forget anything.", "cites": ["src:2"] },
            { "situation": "when_refusing", "verbatim": "[Vendor] does a very poor job of summarizing...often boiling down a 90-120 minute visit to just a few sentences", "cites": ["src:2"] },
            { "situation": "when_refusing", "verbatim": "English as a second language is definitely a potential barrier, so I'm not using it if I have a translator that I'm working with for a patient.", "cites": ["src:3"] },
            { "situation": "venting", "verbatim": "I was very excited to start it, to start the, you know, I just was disappointed, you know, that, that it really wasn't helping.", "cites": ["src:3"] }
          ],
          "costs_them": "Time spent learning a tool that does not fit their visits.",
          "fears": "Being counted as a low adopter for a fit problem that is not theirs.",
          "dream_outcome": "A draft shaped for their specialty, including exam-heavy and interpreter-mediated visits."
        },
        "economic_buyer": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "I think it's hard for people to change in what they already do... And mainly the rate limiting factor is that I always forget my phone, to bring my phone in the patient's room.", "cites": ["src:3"] }
          ],
          "costs_them": "Paid seats sitting idle, which is the fastest way to destroy the ROI case.",
          "fears": "An enterprise contract priced for full adoption against real adoption under half.",
          "dream_outcome": "Even adoption across specialties, so the licence count matches the usage count."
        }
      },
      "segments": ["seg:system", "seg:specialty"],
      "feature_ref": "feat:clinician",
      "cites": ["src:2", "src:3"]
    },
    {
      "id": "pain:note-does-not-support-the-code",
      "statement": "The note reads beautifully and still does not have what I need to bill the level of service that was actually done.",
      "element": "b2b:functional:improved_top_line",
      "shape": {
